arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>" -d "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d.get('error')); sys.exit()
for u in d['members']:
    name=(u.get('profile',{}).get('real_name') or '')
    if 'leo' in name.lower() or 'park' in name.lower():
        print(u['id'], '|', name, '|', u.get('deleted'))
"

